### What problem would this solve?

1. After using the note that are blurred, they are visible to everyone. 
2. In a long note, to unblur the content, one has to scroll down to ublur.

### What would you like to happen?

1. Add a "blur" button potentially on the memos' top right icon to reblur to unblurred content. 
potentially somewhere here:
<img width="240" height="238" alt="Image" src="https://github.com/user-attachments/assets/bfd7a7e7-eacf-4af0-a2e1-27b9aee80ed3" />

2. In a long note, to unblur the content, one has to scroll down to ublur. Potentially move the "click to show sensitive content" button to a fixed position closer to the top, so that it's not determined by how long the memos are. 

<img width="781" height="830" alt="Image" src="https://github.com/user-attachments/assets/4f50fa87-d58f-48d4-aa7c-81c43ab77b19" />

### Additional context

At the moment, I use this JS script for the whole memos instance as a workaround, but need to be improve, the button obscure the existing button.
```
const sensitiveTags = ["#secret", "#sensitive"];

function blurIfSensitive(article) {
  if (article.dataset.blurChecked) return;
  article.dataset.blurChecked = "true";

  setTimeout(() => {
    const text = article.innerText.toLowerCase();
    const isSensitive = sensitiveTags.some(tag => text.includes(tag));

    if (isSensitive) {
      // Apply blur
      Object.assign(article.style, {
        filter: "blur(8px)",
        userSelect: "none",
        transition: "filter 0.3s ease",
        cursor: "pointer",
        position: "relative",
      });

      // Create re-blur button (hidden initially)
      const reBlurBtn = document.createElement("button");
      reBlurBtn.innerText = "🔒 Blur again";
      Object.assign(reBlurBtn.style, {
        position: "absolute",
        top: "8px",
        right: "8px",
        zIndex: "999",
        display: "none",
        padding: "2px 8px",
        fontSize: "11px",
        borderRadius: "6px",
        border: "1px solid #ccc",
        background: "#fff",
        cursor: "pointer",
        opacity: "0.85",
      });
      article.appendChild(reBlurBtn);

      // Click article to unblur
      article.addEventListener("click", (e) => {
        if (e.target === reBlurBtn) return; // let button handle its own click
        if (article.style.filter !== "none") {
          article.style.filter = "none";
          article.style.userSelect = "auto";
          article.style.cursor = "default";
          reBlurBtn.style.display = "block";
        }
      });

      // Click button to re-blur
      reBlurBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        article.style.filter = "blur(8px)";
        article.style.userSelect = "none";
        article.style.cursor = "pointer";
        reBlurBtn.style.display = "none";
      });
    }
  }, 300);
}

const main = document.getElementsByTagName("main")[0];
Array.from(main.getElementsByTagName("article")).forEach(blurIfSensitive);

const observer = new MutationObserver(mutations => {
  mutations.forEach(mutation => {
    mutation.addedNodes.forEach(node => {
      if (node.nodeType !== Node.ELEMENT_NODE) return;
      if (node.tagName === "ARTICLE") blurIfSensitive(node);
      node.querySelectorAll("article").forEach(blurIfSensitive);
    });
  });
});

observer.observe(main, { childList: true, subtree: true });

```
